// A bounded, deterministic teaching simulation. Never queries or changes a real cluster.
export const requestFlowId='learn-request-complete';
const network=(from,to,title,protocol,port,initiator,phase,exchange,text,packetLabel)=>({from,to,title,relation:'network',channel:'traffic',kind:'Example network exchange',transport:{protocol,serverPort:port,initiator},phase,exchange,text,packetLabel,packet:`${protocol} · server :${port} · initiator: ${initiator} · ${phase} · ${packetLabel}`});
export const requestSteps=[
 network('users','public-dns','Ask for the application address','DNS / UDP',53,'users','request','dns','A client resolver asks for shop.example.invalid. This summarizes DNS resolution; DNS is separate from HTTP.','DNS query'),
 network('public-dns','users','Receive the DNS answer','DNS / UDP',53,'users','response','dns','The resolver returns the example entry address 192.0.2.10. It does not forward the subsequent web request.','DNS answer'),
 network('users','load-balancer','Start the public TLS connection','HTTPS / TCP',443,'users','request','public','The client connects to the public listener and validates its certificate. This example terminates TLS at the load balancer.','HTTPS GET /'),
 network('load-balancer','ingress','Open the private backend connection','HTTP / TCP',80,'load-balancer','request','edge','The load balancer starts a separate HTTP :80 backend connection to the Ingress controller. Other deployments can re-encrypt this boundary.','HTTP GET /'),
 {from:'service',to:'pod-a',title:'Resolve an eligible application endpoint',relation:'configuration',channel:'logical',kind:'Logical backend selection',transport:null,exchange:null,text:'Ingress configuration refers to Service web:80. Its selector app=web and EndpointSlices identify ready endpoints. This example controller uses a Pod endpoint directly; the Service is not another HTTP process or obligatory proxy hop.',packetLabel:'Selector + ready endpoint',packet:'No transport port · Service reference / EndpointSlice selection'},
 network('ingress','app-a','Connect to the application process','HTTP / TCP',8080,'ingress','request','app','The controller opens a connection to Pod IP 10.244.1.7:8080. The host supplies networking; containers in the Pod share its network namespace. The application process owns the listening socket.','HTTP GET / → app'),
 network('app-a','ingress','Return the application result','HTTP / TCP',8080,'ingress','response','app','The application returns HTTP 200 on that backend connection. Readiness and application response are different evidence.','HTTP 200 + body'),
 network('ingress','load-balancer','Return through the edge backend','HTTP / TCP',80,'load-balancer','response','edge','The Ingress controller returns the result over the load balancer’s established backend connection.','HTTP 200 upstream'),
 network('load-balancer','users','Return the encrypted client response','HTTPS / TCP',443,'users','response','public','The public listener returns the result over the client TLS connection. DNS, the API server, scheduler and etcd do not forward this HTTP response.','HTTPS 200 → client')
];
export function installRequestLab(flows){flows[requestFlowId]={label:'Kubernetes · browser to app and back',color:0x76dfff,steps:requestSteps};}
export const requestProfile={id:'request-lab',label:'Kubernetes request lab',flowId:requestFlowId,nodeIds:['cluster','control-plane','api','worker-a','pod-a','app-a','ingress','service','users','public-dns','load-balancer','readiness','network-policy','env'],overview:['cluster','control-plane','worker-a','pod-a','app-a','ingress','service','users','public-dns','load-balancer'],layout:{cluster:[4,.7,0],'control-plane':[10,1.2,-7],api:[10,1.7,-7],'worker-a':[5,1.2,4],'pod-a':[5,1.8,4],'app-a':[4,2.1,4],ingress:[-7,1.2,-5],service:[0,1.2,-4],users:[-32,.5,4],'public-dns':[-28,.5,-8],'load-balancer':[-20,.5,2],readiness:[6,2.2,5],'network-policy':[0,1.3,9],env:[5,2.2,5]},colors:{traffic:0x6be5ff,logical:0xffcd81}};
