 ingress:{command:cmd+'get ingress web -o yaml',config:'apiVersion: networking.k8s.io/v1\nkind: Ingress\nmetadata: {name: web, namespace: learning}\nspec:\n  ingressClassName: YOUR_INSTALLED_CLASS\n  rules:\n    - host: shop.example.invalid\n      http:\n        paths:\n          - path: /\n            pathType: Prefix\n            backend:\n              service:\n                name: web\n                port: {number: 80}',output:'SIMULATED: controller host/path rule selects Service web:80. An installed controller and reachable listener are prerequisites; this object alone cannot serve traffic.'},
 service:{command:cmd+'get service web -o yaml\n'+cmd+'get endpointslices -l kubernetes.io/service-name=web -o yaml',config:'apiVersion: v1\nkind: Service\nmetadata: {name: web, namespace: learning}\nspec:\n  selector: {app: web}\n  ports:\n    - port: 80\n      targetPort: 8080',output:'SIMULATED: selector app=web; matching Pod web-a; endpoint 10.244.1.7:8080 ready=true.'},
 'pod-a':{command:cmd+'get pod web-a --show-labels\n'+cmd+'describe pod web-a',config:'Example labels: app=web\nPod IP: 10.244.1.7\nContainers: app\nDeclared readiness: GET /ready :8080',output:'SIMULATED: Ready=True; Pod IP shared by its containers. A Pod is not a separate virtual machine.'},
 'app-a':{command:cmd+'logs web-a -c app\n'+cmd+'logs web-a -c app --previous',config:'Example container:\n  name: app\n  image: your-registry.example/learning-app:lab\n  ports: [{containerPort: 8080}]\n  env:\n    - name: DATABASE_URL\n      valueFrom:\n        secretKeyRef: {name: app-config, key: DATABASE_URL}',output:'SIMULATED: app listening on 0.0.0.0:8080; GET / returned 200. Image and configuration are placeholders; no real secret value is shown.'},
