export const requestQuestions=[
 ['What comes back from DNS?',['An address/record answer','The website HTML','A new Pod'],0,'DNS answers naming questions; the client makes its own subsequent web connection.'],
 ['What should the client do next?',['Send HTTP through DNS','Start TLS to the resolved public listener','Write to etcd'],1,'The DNS answer enables a separate connection; it is not an HTTP forwarding hop.'],
 ['How many connections are modeled at the load balancer?',['Only one shared TCP connection','Public client and separate backend connections','One connection to the scheduler'],1,'The public listener terminates TLS and initiates a separate backend connection in this example.'],
 ['What determines the application backend?',['Only the container image name','Service reference, matching selectors and eligible endpoints','The Git branch'],1,'The configured controller uses the Service and endpoint information to choose its backend.'],
 ['Selector app=store; Pod label app=web. What happens?',['The Pod is automatically renamed','This selector finds no matching Pod','The API forwards the request'],1,'A mismatched selector cannot select this Pod, even if that Pod is Ready.'],
 ['Where is the real app listener?',['In the Service YAML process','At the application process socket in the Pod network','Inside public DNS'],1,'Service is configuration/dataplane abstraction. The application process listens on the Pod network address and port.'],
 ['Does the HTTP response go through etcd?',['No','Yes','Only for HTTP 200'],0,'The response uses established application connections; etcd stores Kubernetes API state.'],
 ['Does backend HTTP mean the client response is unencrypted here?',['Yes','No, the public connection still uses TLS','DNS encrypts it'],1,'The load balancer returns the result on the separate public TLS connection. Backend encryption is a separate design choice.'],
 ['Is this successful model proof your real cluster works?',['Yes','No, real endpoints and user outcomes need validation','Only if you zoom in'],1,'All status, packets and outputs on this page are simulated teaching data.']
];
export const requestFaults={
 selector:{label:'Service selector mismatch',stop:4,action:'fix-selector',repair:'Review selector app=web',symptom:'Ready Pod, but Service app=store selects no matching endpoint. Example controller returns 503.',evidence:'SIMULATED: Service selector app=store; Pod web-a label app=web Ready=True; matching endpoints=0.'},
 policy:{label:'Deny application connection',stop:5,action:'allow-ingress',repair:'Review a scoped ingress allow rule',symptom:'The endpoint is ready, but the assumed enforcing policy denies the ingress controller connection. Example result: timeout / gateway failure; no app response.',evidence:'SIMULATED: endpoint 10.244.1.7:8080 ready=true; enforcing dataplane denies controller→app TCP :8080. An HTTP status is controller/time-out dependent.'},
 env:{label:'Missing required environment',stop:4,action:'restore-env',repair:'Restore the required workload/key reference',symptom:'The app exits because DATABASE_URL is missing. This single-endpoint example has no ready application backend.',evidence:'SIMULATED previous-container log: Missing required environment variable DATABASE_URL. Pod restarting; Ready=False; eligible endpoints=0.'}
};
export function createRequestState(){return {step:0,fault:null,corrected:false,verified:false,feedback:'',history:[]};}
export function moveRequest(s,index){const max=s.fault?requestFaults[s.fault].stop:requestSteps.length-1;return {...s,step:Math.max(0,Math.min(index,max)),feedback:''};}
export function injectRequest(s,fault){if(!requestFaults[fault])return s;return {...s,step:requestFaults[fault].stop,fault,corrected:false,verified:false,feedback:'Read the evidence, choose a scoped change, then verify.',history:[...s.history,'Injected: '+requestFaults[fault].label]};}
export function repairRequest(s,action){if(!s.fault)return s;const good=requestFaults[s.fault].action===action;return {...s,corrected:good||s.corrected,feedback:good?'Simulated change applied. Recovery is unverified until endpoint, readiness and user-path checks pass.':'That change does not address this evidence. Re-read the failing boundary.',history:[...s.history,good?'Scoped change applied; awaiting verification':'Rejected an unrelated repair choice']};}
export function verifyRequest(s){if(!s.fault||!s.corrected)return {...s,feedback:'Apply an evidence-matched change before verifying recovery.'};return {...s,fault:null,corrected:false,verified:true,feedback:'SIMULATED verification passed: selector/endpoint match, Pod readiness and HTTPS 200. Resume the flow; this does not verify a real cluster.',history:[...s.history,'Verified in simulation: endpoint + readiness + user response']};}
export function observeRequest(s){if(!s.fault)return {status:s.verified?'Verified in simulation · HTTP 200':'Healthy example · HTTP 200',evidence:'SIMULATED: Service app=web; endpoint 10.244.1.7:8080 ready=true; HTTPS response 200.'};return {status:s.corrected?'Change applied · verification pending':'Blocked · '+requestFaults[s.fault].label,evidence:requestFaults[s.fault].evidence+(s.corrected?'\nCandidate correction applied; the original failure remains gated until simulated verification.':'')};}
export function answerRequest(index,choice){const q=requestQuestions[index];return {correct:choice===q[2],text:(choice===q[2]?'Correct. ':'Try again. ')+q[3]};}
export function boundaryPath(nodes,id){const path=[];let n=nodes.find(n=>n.id===id);while(n){path.unshift(n);n=nodes.find(p=>p.id===n.parent);}const cluster=path.some(n=>n.id==='cluster');const chain=path.filter(n=>['cluster','node','pod','container'].includes(n.kind)).map(n=>n.label);if(cluster)return chain.join(' → ')+(chain.length?' · ':'')+'cluster scope';const town=path.find(n=>n.district);return 'Outside Kubernetes cluster'+(town?' · '+town.label:'');}
export function transportDetails(s,nodes){const name=id=>nodes.find(n=>n.id===id)?.label||id;if(!s.transport)return ['local','configuration','ownership','storage','containment'].includes(s.relation)?'Logical / local relationship. No network initiator or transport port is specified; do not read this arrow as a packet hop.':'Abbreviated legacy boundary: '+s.packet+'. Complete initiator/transport metadata is not recorded for this step; do not infer extra ports or mandatory hops.';const t=s.transport,server=s.phase==='response'?s.from:s.to;return `Initiator: ${name(t.initiator)} · Server: ${name(server)} · ${t.protocol} · server port ${t.serverPort} · ${s.phase||'configured exchange'}. ${s.phase==='response'?'Response returns from the server port to the initiator’s client port.':'Client/source ports are chosen independently; the displayed port belongs to the server listener.'}`;}
